const axios = require("axios");
const cheerio = require("cheerio");
const allowedApiKeys = require("../../declaration/arrayKey.jsx");

module.exports = async (req, res) => {
  const query = req.query.query;
  const apiKey = req.query.apiKey;

  // Validasi input
  if (!query) {
    return res.status(400).json({
      error: "Query pencarian Pinterest tidak ditemukan!",
    });
  }

  if (!apiKey || !allowedApiKeys.includes(apiKey)) {
    return res.status(403).json({
      error: "API Key tidak valid atau tidak diberikan!",
    });
  }

  const url = `https://id.pinterest.com/search/pins/?q=${encodeURIComponent(query)}`;

  try {
    const response = await axios.get(url, {
      headers: {
        "cookie": "_auth=1; _b=\"AVna7S1p7l1C5I9u0+nR3YzijpvXOPc6d09SyCzO+DcwpersQH36SmGiYfymBKhZcGg=\"; _pinterest_; _ir=0", // Tambahkan cookie valid untuk Pinterest di sini
      },
    });

    const $ = cheerio.load(response.data);
    const results = [];

    $("div > a").each((i, elem) => {
      const imgSrc = $(elem).find("img").attr("src");
      if (imgSrc) {
        results.push({
          url: imgSrc.replace(/236/g, "736"), // Ubah resolusi gambar
        });
      }
    });

    if (results.length === 0) {
      return res.status(404).json({
        error: "Gambar tidak ditemukan untuk pencarian ini.",
      });
    }

    res.status(200).json({
      creator: "kaizel jskai",
      query,
      total_results: results.length,
      images: results,
    });
  } catch (error) {
    res.status(500).json({
      error: "Ada masalah, coba lagi nanti.",
    });
  }
};
